begin;
alter table public.vuppi_members add column if not exists quick_delivery_enabled boolean not null default true;
create or replace function public.vuppi_set_quick_delivery(p_member uuid,p_enabled boolean) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
begin if not public.up_platform_is_admin() then raise exception 'UP_CAR: Acesso exclusivo do administrador.'; end if; update vuppi_members set quick_delivery_enabled=p_enabled where user_id=p_member and kind='merchant'; if not found then raise exception 'UP_CAR: Estabelecimento n?o encontrado.'; end if; insert into up_platform_audit(actor_id,action,target,reason,details) values(auth.uid(),'merchant_quick_delivery',p_member::text,'Configura??o de solicita??o r?pida',jsonb_build_object('enabled',p_enabled)); return jsonb_build_object('ok',true); end;$$;
create or replace function public.vuppi_admin_create_delivery(p_data jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare q vuppi_quotes; m vuppi_members; d vuppi_deliveries;
begin if not public.up_platform_is_admin() then raise exception 'UP_CAR: Acesso exclusivo do administrador.'; end if; select * into q from vuppi_quotes where id=(p_data->>'quote_id')::uuid for update; select * into m from vuppi_members where user_id=q.merchant and kind='merchant'; if q.id is null or m.user_id is null or not m.approved or not m.quick_delivery_enabled or q.expires_at<now() then raise exception 'UP_CAR: Cota??o inv?lida, vencida ou modalidade n?o habilitada.'; end if; select * into d from vuppi_deliveries where quote_id=q.id; if d.id is not null then return to_jsonb(d); end if; insert into vuppi_deliveries(quote_id,merchant,city,destination,recipient,phone,lat,lng,pickup_lat,pickup_lng,pickup_address,merchant_name,distance_m,price_cents) values(q.id,m.user_id,m.city,trim(p_data->>'destination'),trim(p_data->>'recipient'),p_data->>'phone',q.lat,q.lng,m.lat,m.lng,m.address,m.name,q.distance_m,q.price_cents) returning * into d; insert into up_platform_audit(actor_id,action,target,reason,details) values(auth.uid(),'delivery_admin_create',d.id::text,'Solicita??o r?pida pela central',jsonb_build_object('merchant',m.user_id)); return to_jsonb(d); end;$$;
grant execute on function public.vuppi_set_quick_delivery(uuid,boolean),public.vuppi_admin_create_delivery(jsonb) to authenticated;
commit;
